from pathlib import Path


def replace_once(path: str, old: str, new: str) -> None:
    p = Path(path)
    text = p.read_text()
    if old not in text:
        raise RuntimeError(f'Pattern not found in {path}: {old[:140]!r}')
    p.write_text(text.replace(old, new, 1))


